package com.rpsbattle.tournament;
import com.rpsbattle.account.AccountAuthorizationService;import com.rpsbattle.tournament.domain.*;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Service;import java.time.Instant;import java.util.*;
@Service public class ParticipantTournamentStateService {
 private final TournamentService tournaments;private final OwnedTournamentService owned;private final AccountAuthorizationService accounts;
 public ParticipantTournamentStateService(TournamentService tournaments,OwnedTournamentService owned,AccountAuthorizationService accounts){this.tournaments=tournaments;this.owned=owned;this.accounts=accounts;}
 public Map<String,Object> me(Authentication auth,String id){var actor=accounts.requireUser(auth);var t=tournaments.find(id);synchronized(t){var mine=t.registrations.stream().filter(r->r.userId().equals(actor.id().value())).toList();var mineIds=mine.stream().map(r->r.id().toString()).collect(java.util.stream.Collectors.toSet());var ranks=mine.isEmpty()?Map.<String,com.rpsbattle.tournament.ranking.RankingEntry>of():tournaments.ranking(t).stream().filter(row->mineIds.contains(row.participantId())).collect(java.util.stream.Collectors.toMap(com.rpsbattle.tournament.ranking.RankingEntry::participantId,r->r));var states=new ArrayList<Map<String,Object>>();
  for(var r:mine){var row=new LinkedHashMap<String,Object>();String key=r.id().toString();var participant=t.participants.stream().filter(p->p.participantId().equals(key)).findFirst();
   var games=t.matches.stream().filter(m->m.participantA.participantId().equals(key)||m.participantB.participantId().equals(key)).toList();var running=games.stream().filter(m->m.status==TournamentMatch.Status.RUNNING).findFirst();var next=games.stream().filter(m->m.status==TournamentMatch.Status.PENDING).min(Comparator.comparingInt(m->m.round));
   String status=switch(r.status()){case PENDING->"PENDING_APPROVAL";case REJECTED->"REJECTED";case CANCELLED->"WITHDRAWN";case NOT_CHECKED_IN->"MISSED_CHECK_IN";case APPROVED->t.checkInRequired&&t.status==TournamentStatus.CHECK_IN?"CHECK_IN_REQUIRED":"APPROVED";case CHECKED_IN->"CHECKED_IN";};
   if(participant.isPresent()&&t.operations.active(key)&&List.of(TournamentStatus.RUNNING,TournamentStatus.PAUSED,TournamentStatus.RECOVERY_REQUIRED,TournamentStatus.FINISHED).contains(t.status)){
    status=running.isPresent()?"PLAYING":next.isPresent()?"WAITING_MATCH":"WAITING_ROUND";
    if(com.rpsbattle.tournament.scheduler.GroupKnockoutScheduler.hasKnockout(t)&&t.bracket.stream().anyMatch(n->n.resolution()!=null&&(key.equals(n.slotA())||key.equals(n.slotB()))&&!key.equals(n.winnerParticipantId())))status="ELIMINATED";
    if(t.groupHistory.stream().anyMatch(stage->!stage.qualifiers().contains(key))||t.groupStage!=null&&t.groupStage.locked()&&!t.groupStage.qualifiers().contains(key))status="ELIMINATED";
    if(t.status==TournamentStatus.FINISHED){var champion=tournaments.champion(t);status=champion!=null&&key.equals(champion.participantId())?"CHAMPION":status.equals("ELIMINATED")?status:"FINISHED";}
   }
   if(t.format==TournamentFormat.TEAM_ROUND_ROBIN&&t.status==TournamentStatus.FINISHED&&t.operations.active(key)){String winner=com.rpsbattle.tournament.scheduler.TeamScheduler.winner(t);if(winner!=null&&t.teams.teams().stream().anyMatch(team->team.id().equals(winner)&&team.roster().contains(key)))status="CHAMPION";}
   if(next.isPresent()&&r.botId()==null&&t.readyWindows.containsKey(next.get().id)&&t.status==TournamentStatus.RUNNING){var window=t.readyWindows.get(next.get().id);status=window.confirmed().contains(key)?"READY_CONFIRMED":"READY_CHECK";}if(t.operations.participants().containsKey(key))status=t.operations.participants().get(key).name();if(t.status==TournamentStatus.CANCELLED&&r.status()!=TournamentRegistration.Status.NOT_CHECKED_IN)status="TOURNAMENT_CANCELLED";
   row.put("missedReady",games.stream().anyMatch(m->"NO_SHOW".equals(m.failure)&&!key.equals(m.winnerParticipantId)));row.put("registration",r);row.put("participantId",participant.map(TournamentParticipant::participantId).orElse(null));row.put("status",status);row.put("nextMatch",next.map(m->match(t,m,key)).orElse(null));row.put("currentMatch",running.map(m->match(t,m,key)).orElse(null));row.put("deadline",t.status==TournamentStatus.CHECK_IN?t.timing.checkInDeadline():t.timing.registrationDeadline());
   if(t.swiss!=null){row.put("swissHistory",swissHistory(t,key));row.put("swiss",t.swiss);row.put("buchholz",com.rpsbattle.tournament.scheduler.SwissScheduler.buchholz(t,key));row.put("byeRounds",t.rounds.stream().filter(round->round.byeParticipantIds().contains(key)).map(TournamentRound::number).toList());}
   if(t.format==TournamentFormat.TEAM_ROUND_ROBIN){var team=t.teams.teams().stream().filter(x->x.roster().contains(key)).findFirst().orElse(null);row.put("team",team);row.put("captain",team!=null&&actor.id().value().equals(team.captain()));}
   if(t.groupStage!=null){String group=t.groupStage.groups().entrySet().stream().filter(e->e.getValue().contains(key)).map(Map.Entry::getKey).findFirst().orElse(null);row.put("group",group);row.put("qualified",t.groupStage.locked()&&t.groupStage.qualifiers().contains(key));row.put("groupRank",group==null?null:com.rpsbattle.tournament.scheduler.GroupKnockoutScheduler.standings(t,group).stream().filter(rank->rank.participantId().equals(key)).findFirst().orElse(null));}
   row.put("rank",ranks.get(key));if(r.status()==TournamentRegistration.Status.REJECTED)row.put("rejectionReason",tournaments.registrationRejectionReason(t,key));states.add(row);
  }
  return Map.of("teamLineups",com.rpsbattle.tournament.scheduler.TeamScheduler.privateLineups(t,actor.id().value()),"tournamentId",id,"tournamentStatus",t.status,"revision",t.revision,"serverTime",Instant.now(),"states",states);
 }}
 private List<Map<String,Object>> swissHistory(Tournament t,String key){var rows=new ArrayList<Map<String,Object>>();for(var round:t.rounds){if(round.byeParticipantIds().contains(key)){rows.add(Map.of("round",round.number(),"opponent","BYE","result","+3 điểm · Không tạo trận"));continue;}TournamentSeries.roots(t).stream().filter(m->m.round==round.number()&&(key.equals(m.participantA.participantId())||key.equals(m.participantB.participantId()))).findFirst().ifPresent(m->{var decision=TournamentSeries.decision(t,m);rows.add(Map.of("round",round.number(),"opponent",key.equals(m.participantA.participantId())?m.participantB.displayName():m.participantA.displayName(),"result",decision.map(d->"DOUBLE_FORFEIT".equals(d.decisionReason)?"LOSS":d.winnerParticipantId==null?"DRAW":key.equals(d.winnerParticipantId)?"WIN":"LOSS").orElse("NEXT")));});}return rows;}
 private Map<String,Object> match(Tournament t,TournamentMatch m,String participant){var result=new LinkedHashMap<String,Object>();result.put("id",m.id);result.put("round",m.round);result.put("seriesId",m.seriesId);result.put("gameNumber",m.gameNumber);result.put("bestOf",t.bestOf);result.put("series",TournamentSeries.view(t,t.matches.stream().filter(game->game.id.equals(m.seriesId)).findFirst().orElse(m)));result.put("opponent",m.participantA.participantId().equals(participant)?m.participantB.displayName():m.participantA.displayName());result.put("scheduledAt",m.scheduledAt);result.put("onlineMatchId",m.onlineMatchId);result.put("historyMatchId",m.historyMatchId);var window=t.readyWindows.get(m.id);if(window!=null){result.put("readyWindowId",window.id());result.put("readyDeadline",window.deadline());result.put("readyConfirmed",window.confirmed().contains(participant));}return result;}
}
